static const int32 GM1LevelSpawnTableCount = UE_ARRAY_COUNT(GM1LevelSpawnTable);

static TArrayView<const FM1MonsterSpawn> M1SpawnsForLevel(const FString& MapName)
{
	for (const FM1LevelSpawns& Level : GM1LevelSpawnTable)
	{
		if (MapName.Contains(Level.LevelName, ESearchCase::IgnoreCase))
		{
			return TArrayView<const FM1MonsterSpawn>(Level.Spawns, Level.Count);
		}
	}
	return TArrayView<const FM1MonsterSpawn>();
}
